create policy "public read site images" on storage.objects for select using (bucket_id = 'site-images');
create policy "staff upload site images" on storage.objects for insert to authenticated with check (bucket_id = 'site-images' and (public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'editor')));
create policy "staff update site images" on storage.objects for update to authenticated using (bucket_id = 'site-images' and (public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'editor')));
create policy "staff delete site images" on storage.objects for delete to authenticated using (bucket_id = 'site-images' and (public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'editor')));